        [TestMethod]
        public void Request_Type_Has_To_Be_A_Record_Type()
        {
            var requestTypeIsNotARecord = (from handler in MediatorImplementations
                                              where handler.Request is not null &&
                                                    handler.Request.GetType() != typeof(Record)
                                              select new
                                              {
                                                  Error = $@"

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Fullname: {handler.Request.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Request:  {handler.Request.SyntaxTree}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:   {handler.Request.SyntaxTree.Replace(" class ", " record ")}       
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                              }).ToImmutableList();


            Assert.IsTrue(requestTypeIsNotARecord.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00004

Please use record types for your request types. To go sure that during processing your request nobody
is able to manipulate the ongoing process by changing the state of the request object.

Found:{requestTypeIsNotARecord.Count}

{requestTypeIsNotARecord.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
